void can_sync_init( Can_Dev_Id dev_id , UInt8 size   ) 
{
    Can_Sync_Node *can_sync_node ; 
    UInt8 i ; 
    
    can_sync[dev_id].free = fifo_create(); 	
    can_sync[dev_id].exec = fifo_create();
    
    can_sync[dev_id].res  = os_res_create(); 		
    
    for( i = 0 ; i < size ; i ++ )
    {
        can_sync_node = can_sync_node_free_create();
                
        fifo_insert( can_sync[dev_id].free , (Fifo_Node*) can_sync_node ); 
    }	
    
    can_usr_rx_reg_fast( dev_id , (dev_id == CAN_DEV_1) ? (Reg_Func)can_sync_execute_dev1 : (Reg_Func)can_sync_execute_dev0 );
}

